function sanityCheck(json) {
    if (json.status != true) {
        node.error("Invalid Tibber result!", msg);
        return false;
    }
    var jDate = new Date(json.datum);
    var tDate = new Date();
    tDate.setHours(0, 0, 0, 0);

    if (jDate.getTime() < tDate.getTime()) {
        node.error("Incorrect date in Tibber result!");
        return false;
    }

    //We should have at least 24 data items (96 for quarter prices)
    let tot_results = Object.keys(json.data).length;
    if (tot_results < 24) {
        node.error("Incorrect data in Tibber result!");
        return false;
    }
    return true;
}

function calculate_charge_schema(data, noChargeAfterLastDischarge = true) {
    const processedData = JSON.parse(JSON.stringify(data)); // Deep copy

    const bIsQuarterData = (processedData.length > 24);
    const blockMultiply = bIsQuarterData ? 0.25 : 1;

    const calc_charge_rate    = context.global.batt_charge_rate    * blockMultiply;
    const calc_discharge_rate = calc_charge_rate; // must equal calc_charge_rate so each discharge moves exactly -1 DP level

    const batt_min = context.flow.batt_min_charged;
    const batt_max = context.global.batt_capacity;
    const n = processedData.length;

    const charge_efficiency    = context.global.batt_charge_efficiency    !== undefined ? context.global.batt_charge_efficiency    : 0.907;
    const discharge_efficiency = context.global.batt_discharge_efficiency !== undefined ? context.global.batt_discharge_efficiency : 0.896;

    // Discretise SOC into integer levels.
    // Level k represents: min(batt_max, batt_min + k * calc_step)
    // calc_step is the rounded calc_charge_rate; the floor/ceil pairing on
    // discharge/charge transitions prevents energy-aliasing without needing
    // a GCD-based step (which collapses to 0.25 Wh with fractional rates,
    // creating ~173k levels and making the DP extremely slow).
    const calc_step = Math.round(calc_charge_rate);
    const maxLevel = Math.ceil((batt_max - batt_min) / calc_step);

    function socAtLevel(k) {
        return Math.min(batt_max, batt_min + k * calc_step);
    }

    // The threshold is baked into the discharge profit: earn (price - threshold) per kWh
    // instead of price. This means the DP only discharges when the spread over the actual
    // charge cost exceeds price_min_sell_difference, regardless of when/what was charged.

    // --- Forward dynamic programming ---
    // dp[k]          = best profit achievable up to (and including) the current slot,
    //                  with the battery ending at level k.
    // bt[slot][k]    = { action, from } backtrack entry: which action at this slot, and
    //                  which incoming level k led to outgoing level k.
    let dp = new Float64Array(maxLevel + 1).fill(-Infinity);
    dp[0] = 0; // Battery starts at batt_min (level 0), profit = 0

    // Allocate backtrack as flat arrays for speed
    const btAction = new Uint8Array(n * (maxLevel + 1)); // 0=idle, 1=charge, 2=discharge
    const btFrom   = new Uint32Array(n * (maxLevel + 1));
    const ACTION_IDLE = 0, ACTION_CHARGE = 1, ACTION_DISCHARGE = 2;

    for (let i = 0; i < n; i++) {
        const price = processedData[i].hour_price;
        const newDp = new Float64Array(maxLevel + 1).fill(-Infinity);
        const base  = i * (maxLevel + 1);

        for (let k = 0; k <= maxLevel; k++) {
            if (dp[k] === -Infinity) continue;
            const soc = socAtLevel(k);

            // Option: idle — stay at level k
            if (dp[k] > newDp[k]) {
                newDp[k] = dp[k];
                btAction[base + k] = ACTION_IDLE;
                btFrom[base + k]   = k;
            }

            // Option: charge — battery must not be full.
            // Use ceil so the level only advances when a full step has been added;
            // this prevents the top-level aliasing that would let the DP "create" energy.
            if (soc < batt_max) {
                const power  = Math.min(calc_charge_rate, batt_max - soc);
                const newK   = Math.min(maxLevel, Math.ceil((soc + power - batt_min) / calc_step));
                const profit = dp[k] - (power / charge_efficiency / 1000) * price;
                if (profit > newDp[newK]) {
                    newDp[newK] = profit;
                    btAction[base + newK] = ACTION_CHARGE;
                    btFrom[base + newK]   = k;
                }
            }

            // Option: discharge — battery must not be empty.
            // Use floor (paired with ceil for charge) so that a discharge from the top
            // level drops by two steps rather than one, preventing the energy-creation
            // aliasing bug. Use (price - threshold) as effective earn rate so the DP
            // only discharges when the spread over the actual charge cost exceeds
            // price_min_sell_difference.
            if (soc > batt_min) {
                const power  = Math.min(calc_discharge_rate, soc - batt_min);
                const newK   = Math.max(0, Math.floor((soc - power - batt_min) / calc_step));
                const profit = dp[k] + (power * discharge_efficiency / 1000) * (price - context.flow.price_min_sell_difference);
                if (profit > newDp[newK]) {
                    newDp[newK] = profit;
                    btAction[base + newK] = ACTION_DISCHARGE;
                    btFrom[base + newK]   = k;
                }
            }
        }

        dp = newDp;
    }

    // Find the ending level with the highest profit
    let bestProfit = -Infinity, bestEndLevel = 0;
    for (let k = 0; k <= maxLevel; k++) {
        if (dp[k] > bestProfit) { bestProfit = dp[k]; bestEndLevel = k; }
    }

    // Backtrack to recover the action sequence
    const actionSeq = new Array(n);
    let curLevel = bestEndLevel;
    for (let i = n - 1; i >= 0; i--) {
        const base = i * (maxLevel + 1);
        const a = btAction[base + curLevel];
        actionSeq[i] = a === ACTION_CHARGE ? 'charge' : a === ACTION_DISCHARGE ? 'discharge' : 'idle';
        curLevel = btFrom[base + curLevel];
    }

    processedData.forEach((item, i) => { item.hour_type = actionSeq[i]; });

    // Remove charges that fall after the last discharge (no point charging with no sale)
    if (noChargeAfterLastDischarge) {
        let lastDischargeIndex = -1;
        for (let i = n - 1; i >= 0; i--) {
            if (processedData[i].hour_type === 'discharge') { lastDischargeIndex = i; break; }
        }
        if (lastDischargeIndex !== -1) {
            for (let i = lastDischargeIndex + 1; i < n; i++) {
                if (processedData[i].hour_type === 'charge') processedData[i].hour_type = 'idle';
            }
        }
    }

    // Final pass: compute battery capacity, setpoints and earned money
    let battery_capacity_watt = batt_min;
    let earned_money = 0.0;

    processedData.forEach(item => {
        if (item.hour_type === 'charge') {
            const power_2_add = Math.min(calc_charge_rate, batt_max - battery_capacity_watt);
            if (power_2_add > 0) {
                battery_capacity_watt += power_2_add;
                earned_money -= (power_2_add / charge_efficiency / 1000) * item.hour_price;
            }
            item.setpoint = context.global.charge_rate;
        } else if (item.hour_type === 'discharge') {
            const power_2_sub = Math.max(0, Math.min(calc_discharge_rate, battery_capacity_watt - batt_min));
            if (power_2_sub > 0) {
                battery_capacity_watt -= power_2_sub;
                earned_money += (power_2_sub * discharge_efficiency / 1000) * item.hour_price;
                item.setpoint = context.global.discharge_rate;
            } else {
                item.hour_type = 'idle';
                item.setpoint = context.global.idle_rate;
            }
        } else {
            item.setpoint = context.global.idle_rate;
        }
        item.battery_capacity_watt = battery_capacity_watt;
        item.battery_capacity_percentage = parseFloat(((100.0 / batt_max) * battery_capacity_watt).toFixed(2));
        item.earned_money = parseFloat(earned_money.toFixed(4));
    });

    return processedData;
}

let ret = {
    "status": false
};

const json = msg.payload;

if (sanityCheck(json) == false) {
    msg.payload = ret;
    return msg;
}

ret.status = true;
ret.datum = json.datum;
ret.data = calculate_charge_schema(json.data);
msg.payload = ret;
return msg;
